40	/// Create a short description of a font family.
41	pub fn summarize_font_family<'a>(
42	    variants: impl IntoIterator<Item = &'a FontInfo>,
43	) -> EcoString {
44	    use typst::text::Tag;
45	
46	    let mut count = 0;
47	    let mut variable = false;
48	    let mut has_italics = false;
49	    let mut has_obliques = false;
50	    let mut supports_opsz = false;
51	    let mut weight_range = MetricRange::default();
52	    let mut stretch_range = MetricRange::default();
53	    let mut variations = IndexMap::<Tag, MetricRange<Scalar>>::new();
54	
55	    for info in variants {
56	        let axes = StandardAxes::parse(&info.axes);
57	
58	        variable |= info.flags.contains(FontFlags::VARIABLE);
59	        has_italics |= info.variant.style == FontStyle::Italic || axes.ital.is_some();
60	        has_obliques |= info.variant.style == FontStyle::Oblique || axes.slnt.is_some();
61	        supports_opsz |= axes.opsz.is_some();
62	
63	        weight_range.expand(info.variant.weight);
64	        stretch_range.expand(info.variant.stretch);
65	
66	        if let Some(axis) = axes.wght {
67	            weight_range.expand_axis(axis, FontWeight::from_wght);
68	        }
69	
70	        if let Some(axis) = axes.wdth {
71	            stretch_range.expand_axis(axis, FontStretch::from_wdth);
72	        }
73	
74	        for axis in &info.axes {
75	            if !StandardAxes::knows(axis.tag) {
76	                variations
77	                    .entry(axis.tag)
78	                    .or_default()
79	                    .expand_axis(axis, |v| Scalar::new(v.0.into()));
80	            }
81	        }
82	
83	        count += 1;
84	    }
85	
86	    let mut detail = EcoString::new();
87	
88	    if variable {
89	        write!(detail, "Variable.").unwrap();
90	    } else {
91	        write!(detail, "{count} variant{}.", if count == 1 { "" } else { "s" }).unwrap();
92	    }
93	
94	    if let Some(range) = weight_range.display_if_not_default() {
95	        write!(detail, " Weight {range}.").unwrap();
96	    }
97	
98	    if let Some(range) = stretch_range.display_if_not_default() {
99	        write!(detail, " Stretch {range}.").unwrap();
100	    }
101	
102	    if has_italics {
103	        detail.push_str(" Has italics.");
104	    }
105	
106	    if has_obliques {
107	        detail.push_str(" Has obliques.");
108	    }
109	
110	    if supports_opsz {
111	        detail.push_str(" Supports optical sizing.");
112	    }
113	
114	    for (tag, range) in variations {
115	        if let Some(range) = range.display() {
116	            write!(detail, " {} {range}.", tag.to_str_lossy()).unwrap();
117	        }
118	    }
119	
120	    detail
121	}
