123	/// A font metric with a minimum and maximum value. Internally tracks an
124	/// uninitialized state.
125	struct MetricRange<T>(Option<(T, T)>);
126	
127	impl<T> MetricRange<T>
128	where
129	    T: Display + Copy + Ord,
130	{
131	    /// Makes sure the range includes the value.
132	    fn expand(&mut self, value: T) {
133	        self.expand_range(value, value);
134	    }
135	
136	    /// Makes sure the range includes all values from the given variation axis.
137	    fn expand_axis(&mut self, axis: &FontAxis, f: impl Fn(AxisValue) -> T) {
138	        self.expand_range(f(axis.min), f(axis.max));
139	    }
140	
141	    /// Makes sure the range includes the minimum and maximum value.
142	    fn expand_range(&mut self, min: T, max: T) {
143	        self.0 = Some(match self.0 {
144	            None => (min, max),
145	            Some((prev_min, prev_max)) => (prev_min.min(min), prev_max.max(max)),
146	        });
147	    }
148	
149	    /// Displays the range if initialized and not the default for that metric.
150	    fn display(self) -> Option<impl Display> {
151	        self.0.map(|(min, max)| {
152	            typst_utils::display(move |f| {
153	                if min == max { write!(f, "{min}") } else { write!(f, "{min}–{max}") }
154	            })
155	        })
156	    }
157	
158	    /// Displays the range if initialized and not the default for that metric.
159	    fn display_if_not_default(self) -> Option<impl Display>
160	    where
161	        T: Default,
162	    {
163	        let default = T::default();
164	        Self(self.0.filter(|&(min, max)| min != default || max != default)).display()
165	    }
166	}
167	
168	impl<T> Default for MetricRange<T> {
169	    fn default() -> Self {
170	        Self(None)
171	    }
172	}
173	
174	/// The global definitions at the given node.
175	pub fn globals<'a>(world: &'a dyn IdeWorld, leaf: &LinkedNode) -> &'a Scope {
176	    let library = world.library();
177	    if leaf.mode_after() == Some(SyntaxMode::Math) {
178	        library.math.scope()
179	    } else {
180	        library.global.scope()
181	    }
182	}
183	
184	/// Checks whether the given value or any of its constituent parts satisfy the
185	/// predicate.
186	pub fn check_value_recursively(
187	    value: &Value,
188	    predicate: impl Fn(&Value) -> bool,
189	) -> bool {
190	    let mut searcher = Searcher { steps: 0, predicate, max_steps: 1000 };
191	    match searcher.find(value) {
192	        ControlFlow::Break(matching) => matching,
193	        ControlFlow::Continue(()) => false,
194	    }
195	}
196	
197	/// Recursively searches for a value that passes the filter, but without
198	/// exceeding a maximum number of search steps.
199	struct Searcher<F> {
200	    max_steps: usize,
201	    steps: usize,
202	    predicate: F,
203	}
204	
205	impl<F> Searcher<F>
206	where
207	    F: Fn(&Value) -> bool,
208	{
209	    fn find(&mut self, value: &Value) -> ControlFlow<bool> {
210	        if (self.predicate)(value) {
211	            return ControlFlow::Break(true);
212	        }
213	
214	        if self.steps > self.max_steps {
215	            return ControlFlow::Break(false);
216	        }
217	
218	        self.steps += 1;
219	
220	        match value {
221	            Value::Dict(dict) => {
222	                self.find_iter(dict.iter().map(|(_, v)| v))?;
223	            }
224	            Value::Content(content) => {
225	                self.find_iter(content.fields().iter().map(|(_, v)| v))?;
226	            }
227	            Value::Module(module) => {
228	                self.find_iter(module.scope().iter().map(|(_, b)| b.read()))?;
229	            }
230	            _ => {}
231	        }
232	
233	        ControlFlow::Continue(())
234	    }
235	
236	    fn find_iter<'a>(
237	        &mut self,
238	        iter: impl Iterator<Item = &'a Value>,
239	    ) -> ControlFlow<bool> {
240	        for item in iter {
241	            self.find(item)?;
242	        }
243	        ControlFlow::Continue(())
244	    }
245	}
