248	mod tests {
249	    use typst::text::{FontBook, FontInfo};
250	
251	    use super::*;
252	
253	    #[test]
254	    fn test_summarize_font_family() {
255	        let book = FontBook::from_infos(
256	            typst_dev_assets::fonts().filter_map(|data| FontInfo::new(data, 0)),
257	        );
258	
259	        let summarize = |family: &str| {
260	            summarize_font_family(
261	                book.select_family(&family.to_lowercase())
262	                    .map(|id| book.info(id).unwrap()),
263	            )
264	        };
265	
266	        // Static.
267	        assert_eq!(summarize("Cascadia Mono"), "2 variants. Weight 400–700.");
268	        assert_eq!(summarize("HK Grotesk"), "16 variants. Weight 100–900. Has italics.");
269	        assert_eq!(
270	            summarize("IBM Plex Sans"),
271	            "5 variants. Weight 300–700. Stretch 75%–100%."
272	        );
273	
274	        // Variable.
275	        assert_eq!(summarize("Cantarell"), "Variable. Weight 100–800.");
276	        assert_eq!(
277	            summarize("Fraunces"),
278	            "Variable. Weight 100–900. Has italics. \
279	             Supports optical sizing. SOFT 0–100. WONK 0–1."
280	        );
281	        assert_eq!(
282	            summarize("Mona Sans"),
283	            "Variable. Weight 200–900. Stretch 75%–125%. Has italics. \
284	             Supports optical sizing."
285	        );
286	    }
287	}
